1	// Port of PyYAML's tokens.py. `id` strings are the ones PyYAML quotes back in
2	// parser error messages ("expected ',' or ']', but got '<stream end>'").
3	
4	class Token {
5	  constructor(startMark, endMark) {
6	    this.startMark = startMark;
7	    this.endMark = endMark;
8	  }
9	}
10	
11	function tokenClass(type, id, fields = []) {
12	  const cls = class extends Token {
13	    constructor(...args) {
14	      const startMark = args[fields.length];
15	      const endMark = args[fields.length + 1];
16	      super(startMark, endMark);
17	      fields.forEach((name, i) => { this[name] = args[i]; });
18	    }
19	  };
20	  Object.defineProperty(cls, 'name', { value: type });
21	  cls.prototype.tokenType = type;
22	  cls.prototype.id = id;
23	  return cls;
24	}
25	
26	export const DirectiveToken = tokenClass('DirectiveToken', '<directive>', ['name', 'value']);
27	export const DocumentStartToken = tokenClass('DocumentStartToken', '<document start>');
28	export const DocumentEndToken = tokenClass('DocumentEndToken', '<document end>');
29	export const StreamStartToken = tokenClass('StreamStartToken', '<stream start>', ['encoding']);
30	export const StreamEndToken = tokenClass('StreamEndToken', '<stream end>');
31	export const BlockSequenceStartToken =
32	  tokenClass('BlockSequenceStartToken', '<block sequence start>');
33	export const BlockMappingStartToken =
34	  tokenClass('BlockMappingStartToken', '<block mapping start>');
35	export const BlockEndToken = tokenClass('BlockEndToken', '<block end>');
36	export const FlowSequenceStartToken = tokenClass('FlowSequenceStartToken', '[');
37	export const FlowMappingStartToken = tokenClass('FlowMappingStartToken', '{');
38	export const FlowSequenceEndToken = tokenClass('FlowSequenceEndToken', ']');
39	export const FlowMappingEndToken = tokenClass('FlowMappingEndToken', '}');
40	export const KeyToken = tokenClass('KeyToken', '?');
41	export const ValueToken = tokenClass('ValueToken', ':');
42	export const BlockEntryToken = tokenClass('BlockEntryToken', '-');
43	export const FlowEntryToken = tokenClass('FlowEntryToken', ',');
44	export const AliasToken = tokenClass('AliasToken', '<alias>', ['value']);
45	export const AnchorToken = tokenClass('AnchorToken', '<anchor>', ['value']);
46	export const TagToken = tokenClass('TagToken', '<tag>', ['value']);
47	
48	export class ScalarToken extends Token {
49	  constructor(value, plain, startMark, endMark, style = null) {
50	    super(startMark, endMark);
51	    this.value = value;
52	    this.plain = plain;
53	    this.style = style;
54	  }
55	}
56	ScalarToken.prototype.tokenType = 'ScalarToken';
57	ScalarToken.prototype.id = '<scalar>';
58	
59	/** True when `token` is an instance of any of the given token classes. */
60	export function isToken(token, ...classes) {
61	  if (token === null || token === undefined) return false;
62	  return classes.some((cls) => token instanceof cls);
63	}
