1	// Port of PyYAML's parser.py — an LL(1) recursive-descent parser driven by an
2	// explicit state machine.
3	//
4	// stream            ::= STREAM-START implicit_document? explicit_document* STREAM-END
5	// implicit_document ::= block_node DOCUMENT-END*
6	// explicit_document ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
7	// block_node_or_indentless_sequence ::=
8	//                       ALIAS
9	//                     | properties (block_content | indentless_block_sequence)?
10	//                     | block_content
11	//                     | indentless_block_sequence
12	// block_node        ::= ALIAS | properties block_content? | block_content
13	// flow_node         ::= ALIAS | properties flow_content? | flow_content
14	// properties        ::= TAG ANCHOR? | ANCHOR TAG?
15	// block_content     ::= block_collection | flow_collection | SCALAR
16	// flow_content      ::= flow_collection | SCALAR
17	// block_collection  ::= block_sequence | block_mapping
18	// flow_collection   ::= flow_sequence | flow_mapping
19	// block_sequence    ::= BLOCK-SEQUENCE-START (BLOCK-ENTRY block_node?)* BLOCK-END
20	// indentless_sequence   ::= (BLOCK-ENTRY block_node?)+
21	// block_mapping     ::= BLOCK-MAPPING_START
22	//                       ((KEY block_node_or_indentless_sequence?)?
23	//                       (VALUE block_node_or_indentless_sequence?)?)*
24	//                       BLOCK-END
25	// flow_sequence     ::= FLOW-SEQUENCE-START
26	//                       (flow_sequence_entry FLOW-ENTRY)*
27	//                       flow_sequence_entry?
28	//                       FLOW-SEQUENCE-END
29	// flow_sequence_entry   ::= flow_node | KEY flow_node? (VALUE flow_node?)?
30	// flow_mapping      ::= FLOW-MAPPING-START
31	//                       (flow_mapping_entry FLOW-ENTRY)*
32	//                       flow_mapping_entry?
33	//                       FLOW-MAPPING-END
34	// flow_mapping_entry    ::= flow_node | KEY flow_node? (VALUE flow_node?)?
35	//
36	// FIRST sets:
37	//
38	// stream: { STREAM-START }
39	// explicit_document: { DIRECTIVE DOCUMENT-START }
40	// implicit_document: FIRST(block_node)
41	// block_node: { ALIAS TAG ANCHOR SCALAR BLOCK-SEQUENCE-START
42	//               BLOCK-MAPPING-START FLOW-SEQUENCE-START FLOW-MAPPING-START }
43	// flow_node: { ALIAS ANCHOR TAG SCALAR FLOW-SEQUENCE-START FLOW-MAPPING-START }
44	// block_content: { BLOCK-SEQUENCE-START BLOCK-MAPPING-START
45	//                  FLOW-SEQUENCE-START FLOW-MAPPING-START SCALAR }
46	// flow_content: { FLOW-SEQUENCE-START FLOW-MAPPING-START SCALAR }
47	// block_collection: { BLOCK-SEQUENCE-START BLOCK-MAPPING-START }
48	// flow_collection: { FLOW-SEQUENCE-START FLOW-MAPPING-START }
49	// block_sequence: { BLOCK-SEQUENCE-START }
50	// block_mapping: { BLOCK-MAPPING-START }
51	// block_node_or_indentless_sequence: { ALIAS ANCHOR TAG SCALAR
52	//        BLOCK-SEQUENCE-START BLOCK-MAPPING-START FLOW-SEQUENCE-START
53	//        FLOW-MAPPING-START BLOCK-ENTRY }
54	// indentless_sequence: { ENTRY }
55	// flow_collection: { FLOW-SEQUENCE-START FLOW-MAPPING-START }
56	// flow_sequence: { FLOW-SEQUENCE-START }
57	// flow_mapping: { FLOW-MAPPING-START }
58	// flow_sequence_entry: { ALIAS ANCHOR TAG SCALAR FLOW-SEQUENCE-START
59	//                        FLOW-MAPPING-START KEY }
60	// flow_mapping_entry: { ALIAS ANCHOR TAG SCALAR FLOW-SEQUENCE-START
61	//                       FLOW-MAPPING-START KEY }
62	
63	import { ParserError } from './errors.mjs';
64	import {
65	  DirectiveToken, DocumentStartToken, DocumentEndToken, StreamEndToken,
66	  BlockSequenceStartToken, BlockMappingStartToken, BlockEndToken,
67	  FlowSequenceStartToken, FlowMappingStartToken, FlowSequenceEndToken,
68	  FlowMappingEndToken, KeyToken, ValueToken, BlockEntryToken, FlowEntryToken,
69	  AliasToken, AnchorToken, TagToken, ScalarToken,
70	} from './tokens.mjs';
71	import {
72	  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
73	  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
74	  MappingStartEvent, MappingEndEvent,
75	} from './events.mjs';
76	
77	export const DEFAULT_TAGS = new Map([
78	  ['!', '!'],
79	  ['!!', 'tag:yaml.org,2002:'],
80	]);
81	
82	// Python's %r for the ASCII strings that reach these messages (token ids and
83	// tag handles): prefer single quotes, switch to double if the value has one.
84	function repr(s) {
85	  const q = s.includes("'") && !s.includes('"') ? '"' : "'";
86	  let out = q;
87	  for (const ch of s) {
88	    if (ch === '\\') out += '\\\\';
89	    else if (ch === q) out += '\\' + ch;
90	    else if (ch === '\n') out += '\\n';
91	    else if (ch === '\r') out += '\\r';
92	    else if (ch === '\t') out += '\\t';
93	    else out += ch;
94	  }
95	  return out + q;
96	}
97	
98	export const ParserMixin = (Base) => class extends Base {
99	  constructor(...args) {
100	    super(...args);
101	    this.currentEvent = null;
102	    this.yamlVersion = null;
103	    this.tagHandles = new Map();
104	    this.states = [];
105	    this.marks = [];
106	    this.state = this.parseStreamStart;
107	  }
108	
109	  dispose() {
110	    // Reset the state attributes (to clear self-references)
111	    this.states = [];
112	    this.state = null;
113	  }
114	
115	  checkEvent(...choices) {
116	    // Check the type of the next event.
117	    if (this.currentEvent === null) {
118	      if (this.state) this.currentEvent = this.state.call(this);
119	    }
120	    if (this.currentEvent !== null) {
121	      if (choices.length === 0) return true;
122	      for (const choice of choices) {
123	        if (this.currentEvent instanceof choice) return true;
124	      }
125	    }
126	    return false;
127	  }
128	
129	  peekEvent() {
130	    // Get the next event.
131	    if (this.currentEvent === null) {
132	      if (this.state) this.currentEvent = this.state.call(this);
133	    }
134	    return this.currentEvent;
135	  }
136	
137	  getEvent() {
138	    // Get the next event and proceed further.
139	    if (this.currentEvent === null) {
140	      if (this.state) this.currentEvent = this.state.call(this);
141	    }
142	    const value = this.currentEvent;
143	    this.currentEvent = null;
144	    return value;
145	  }
146	
147	  parseStreamStart() {
148	    // Parse the stream start.
149	    const token = this.getToken();
150	    const event = new StreamStartEvent(token.startMark, token.endMark, token.encoding);
151	
152	    // Prepare the next state.
153	    this.state = this.parseImplicitDocumentStart;
154	
155	    return event;
156	  }
157	
158	  parseImplicitDocumentStart() {
159	    // Parse an implicit document.
160	    if (!this.checkToken(DirectiveToken, DocumentStartToken, StreamEndToken)) {
161	      this.tagHandles = DEFAULT_TAGS;
162	      const token = this.peekToken();
163	      const startMark = token.startMark;
164	      const endMark = startMark;
165	      const event = new DocumentStartEvent(startMark, endMark, false);
166	
167	      // Prepare the next state.
168	      this.states.push(this.parseDocumentEnd);
169	      this.state = this.parseBlockNode;
170	
171	      return event;
172	    }
173	    return this.parseDocumentStart();
174	  }
175	
176	  parseDocumentStart() {
177	    // Parse any extra document end indicators.
178	    while (this.checkToken(DocumentEndToken)) this.getToken();
179	
180	    // Parse an explicit document.
181	    let event;
182	    if (!this.checkToken(StreamEndToken)) {
183	      let token = this.peekToken();
184	      const startMark = token.startMark;
185	      const [version, tags] = this.processDirectives();
186	      if (!this.checkToken(DocumentStartToken)) {
187	        throw new ParserError(null, null,
188	          `expected '<document start>', but found ${repr(this.peekToken().id)}`,
189	          this.peekToken().startMark);
190	      }
191	      token = this.getToken();
192	      const endMark = token.endMark;
193	      event = new DocumentStartEvent(startMark, endMark, true, version, tags);
194	      this.states.push(this.parseDocumentEnd);
195	      this.state = this.parseDocumentContent;
196	    } else {
197	      // Parse the end of the stream.
198	      const token = this.getToken();
199	      event = new StreamEndEvent(token.startMark, token.endMark);
200	      if (this.states.length) throw new Error('AssertionError: not self.states');
201	      if (this.marks.length) throw new Error('AssertionError: not self.marks');
202	      this.state = null;
203	    }
204	    return event;
205	  }
206	
207	  parseDocumentEnd() {
208	    // Parse the document end.
209	    let token = this.peekToken();
210	    const startMark = token.startMark;
211	    let endMark = startMark;
212	    let explicit = false;
213	    if (this.checkToken(DocumentEndToken)) {
214	      token = this.getToken();
215	      endMark = token.endMark;
216	      explicit = true;
217	    }
218	    const event = new DocumentEndEvent(startMark, endMark, explicit);
219	
220	    // Prepare the next state.
221	    this.state = this.parseDocumentStart;
222	
223	    return event;
224	  }
225	
226	  parseDocumentContent() {
227	    if (this.checkToken(DirectiveToken, DocumentStartToken, DocumentEndToken,
228	      StreamEndToken)) {
229	      const event = this.processEmptyScalar(this.peekToken().startMark);
230	      this.state = this.states.pop();
231	      return event;
232	    }
233	    return this.parseBlockNode();
234	  }
235	
236	  processDirectives() {
237	    this.yamlVersion = null;
238	    this.tagHandles = new Map();
239	    while (this.checkToken(DirectiveToken)) {
240	      const token = this.getToken();
241	      if (token.name === 'YAML') {
242	        if (this.yamlVersion !== null) {
243	          throw new ParserError(null, null,
244	            'found duplicate YAML directive', token.startMark);
245	        }
246	        const [major] = token.value;
247	        if (Number(major) !== 1) {
248	          throw new ParserError(null, null,
249	            'found incompatible YAML document (version 1.* is required)',
250	            token.startMark);
251	        }
252	        this.yamlVersion = token.value;
253	      } else if (token.name === 'TAG') {
254	        const [handle, prefix] = token.value;
255	        if (this.tagHandles.has(handle)) {
256	          throw new ParserError(null, null,
257	            `duplicate tag handle ${repr(handle)}`, token.startMark);
258	        }
259	        this.tagHandles.set(handle, prefix);
260	      }
261	    }
262	    let value;
263	    if (this.tagHandles.size) value = [this.yamlVersion, new Map(this.tagHandles)];
264	    else value = [this.yamlVersion, null];
265	    for (const key of DEFAULT_TAGS.keys()) {
266	      if (!this.tagHandles.has(key)) this.tagHandles.set(key, DEFAULT_TAGS.get(key));
267	    }
268	    return value;
269	  }
270	
271	  parseBlockNode() {
272	    return this.parseNode(true);
273	  }
274	
275	  parseFlowNode() {
276	    return this.parseNode();
277	  }
278	
279	  parseBlockNodeOrIndentlessSequence() {
280	    return this.parseNode(true, true);
281	  }
282	
283	  parseNode(block = false, indentlessSequence = false) {
284	    let event;
285	    if (this.checkToken(AliasToken)) {
286	      const token = this.getToken();
287	      event = new AliasEvent(token.value, token.startMark, token.endMark);
288	      this.state = this.states.pop();
289	    } else {
290	      let anchor = null;
291	      let tag = null;
292	      let startMark = null;
293	      let endMark = null;
294	      let tagMark = null;
295	      if (this.checkToken(AnchorToken)) {
296	        let token = this.getToken();
297	        startMark = token.startMark;
298	        endMark = token.endMark;
299	        anchor = token.value;
300	        if (this.checkToken(TagToken)) {
301	          token = this.getToken();
302	          tagMark = token.startMark;
303	          endMark = token.endMark;
304	          tag = token.value;
305	        }
306	      } else if (this.checkToken(TagToken)) {
307	        let token = this.getToken();
308	        startMark = token.startMark;
309	        tagMark = token.startMark;
310	        endMark = token.endMark;
311	        tag = token.value;
312	        if (this.checkToken(AnchorToken)) {
313	          token = this.getToken();
314	          endMark = token.endMark;
315	          anchor = token.value;
316	        }
317	      }
318	      if (tag !== null) {
319	        const [handle, suffix] = tag;
320	        if (handle !== null) {
321	          if (!this.tagHandles.has(handle)) {
322	            throw new ParserError('while parsing a node', startMark,
323	              `found undefined tag handle ${repr(handle)}`, tagMark);
324	          }
325	          tag = this.tagHandles.get(handle) + suffix;
326	        } else {
327	          tag = suffix;
328	        }
329	      }
330	      // PyYAML keeps the non-specific-tag check commented out here.
331	      if (startMark === null) {
332	        startMark = this.peekToken().startMark;
333	        endMark = startMark;
334	      }
335	      event = null;
336	      let implicit = (tag === null || tag === '!');
337	      if (indentlessSequence && this.checkToken(BlockEntryToken)) {
338	        endMark = this.peekToken().endMark;
339	        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark);
340	        this.state = this.parseIndentlessSequenceEntry;
341	      } else if (this.checkToken(ScalarToken)) {
342	        const token = this.getToken();
343	        endMark = token.endMark;
344	        let scalarImplicit;
345	        if ((token.plain && tag === null) || tag === '!') scalarImplicit = [true, false];
346	        else if (tag === null) scalarImplicit = [false, true];
347	        else scalarImplicit = [false, false];
348	        event = new ScalarEvent(anchor, tag, scalarImplicit, token.value,
349	          startMark, endMark, token.style);
350	        this.state = this.states.pop();
351	      } else if (this.checkToken(FlowSequenceStartToken)) {
352	        endMark = this.peekToken().endMark;
353	        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, true);
354	        this.state = this.parseFlowSequenceFirstEntry;
355	      } else if (this.checkToken(FlowMappingStartToken)) {
356	        endMark = this.peekToken().endMark;
357	        event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, true);
358	        this.state = this.parseFlowMappingFirstKey;
359	      } else if (block && this.checkToken(BlockSequenceStartToken)) {
360	        endMark = this.peekToken().startMark;
361	        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, false);
362	        this.state = this.parseBlockSequenceFirstEntry;
363	      } else if (block && this.checkToken(BlockMappingStartToken)) {
364	        endMark = this.peekToken().startMark;
365	        event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, false);
366	        this.state = this.parseBlockMappingFirstKey;
367	      } else if (anchor !== null || tag !== null) {
